modification.code-pattern:
# Conversation state storage (per user)
conversation_states: dict[int, dict] = {}

def get_conversation_state(user_id: int) -> dict:
    """Get or create conversation state for user"""
    if user_id not in conversation_states:
        conversation_states[user_id] = {
            "status_message_id": None,
            "is_processing": False,
            "pending_messages": [],
            "pending_indicator_message_id": None
        }
    return conversation_states[user_id]

def clear_conversation_state(user_id: int):
    """Clear conversation state after processing completes"""
    if user_id in conversation_states:
        conversation_states[user_id] = {
            "status_message_id": None,
            "is_processing": False,
            "pending_messages": [],
            "pending_indicator_message_id": None
        }

# Get conversation state
state = get_conversation_state(user_id)

# Check if already processing - queue this message as pending
if state["is_processing"]:
    state["pending_messages"].append(message_text)
    pending_count = len(state["pending_messages"])

    if pending_count == 1:
        # First pending message - send indicator
        indicator_msg = await update.message.reply_text(
            "📝 Got it - will handle after current request..."
        )
        state["pending_indicator_message_id"] = indicator_msg.message_id
    else:
        # Update existing indicator with count
        try:
            await context.bot.edit_message_text(
                chat_id=chat_id,
                message_id=state["pending_indicator_message_id"],
                text=f"📝 Added to pending ({pending_count} follow-up messages)..."
            )
        except Exception as e:
            logger.warning(
                "Failed to update pending indicator",
                extra={"user_id": user_id, "error": str(e)}
            )

    logger.info(
        "Message queued as pending",
        extra={
            "user_id": user_id,
            "pending_count": pending_count,
            "event": "message_pending"
        }
    )
    return

# Mark as processing
state["is_processing"] = True

pattern.code-reference:
# Check if we're still rate-limited by Telegram
is_rate_limited = current_time_ms < rate_limit_until

if is_rate_limited and should_update:
    # Skip this edit - we're still rate-limited
    logger.debug("Skipping edit (rate-limited)", ...)

if should_update and not is_rate_limited:
    try:
        await sent_messages[-1].edit_text(html_text, parse_mode=ParseMode.HTML)
        last_update_time = current_time_ms
    except RetryAfter as retry_error:
        # Telegram rate limit - calculate when we can edit again
        rate_limit_until = current_time_ms + (retry_error.retry_after * 1000)

state-management.structure:

{
  user_id: {
    "status_message_id": int | None,           # Message ID of status message
    "is_processing": bool,                     # Whether request is active
    "pending_messages": list[str],             # Queued messages during processing
    "pending_indicator_message_id": int | None # Message ID of pending indicator
  }
}
